481	// rateLimitNakDelay sizes a rate-limited job's redelivery delay to the reset
482	// window carried by the error, clamped to [nakDelay, rateLimitMaxNakDelay]
483	// with a little slack past the reset; without a usable reset instant it falls
484	// back to rateLimitFallbackNakDelay.
485	func rateLimitNakDelay(err error, now time.Time) time.Duration {
486		rl, ok := errors.AsType[*githubapi.RateLimitError](err)
487		if !ok || rl.ResetAt.IsZero() {
488			return rateLimitFallbackNakDelay
489		}
490		delay := rl.ResetAt.Sub(now) + rateLimitNakSlack
491		return min(max(delay, nakDelay), rateLimitMaxNakDelay)
492	}
