func (c *Consumer) nak(ctx context.Context, span trace.Span, msg jetstream.Msg, err error) {
	span.RecordError(err)
	span.SetStatus(otelcodes.Error, "retriable")
	span.SetAttributes(attribute.Bool("entire.error.permanent", false))
	delay := c.nakDelay(deliveryCount(msg))
	slogutil.Warn(ctx, "repo-ops "+string(c.cfg.Op)+" failed; will retry",
		slog.String("subject", msg.Subject()),
		slog.Duration("retry_in", delay),
		slog.String("error", err.Error()),
	)
	recordJobNaked(ctx, c.cfg.Op)
	if nakErr := msg.NakWithDelay(delay); nakErr != nil {
		slogutil.Warn(ctx, "repo-ops nak failed", slog.String("error", nakErr.Error()))
	}
}

// nakDelay grows the redelivery delay geometrically with the delivery count,
// from NakDelay up to nakDelayMax. MaxDeliver is unlimited, so without a
// backoff any op stuck behind a regional/data-plane outage would redeliver
// every NakDelay for hours and hammer a store that is trying to recover. The
// backoff caps that churn while still retrying until the store recovers (or
// the job ages out at StreamMaxAge).
func (c *Consumer) nakDelay(numDelivered uint64) time.Duration {
	if numDelivered <= 1 {
		return c.cfg.NakDelay
	}
	shift := numDelivered - 1
	if shift >= 63 {
		return nakDelayMax
	}
	d := c.cfg.NakDelay << shift
	if d <= 0 { // overflow past the int64 Duration range
		return nakDelayMax
	}
	return min(d, nakDelayMax)
}

// deliveryCount is the message's NumDelivered (1 on first delivery), or 1 when
// metadata is unavailable (e.g. a non-JetStream test message) so the backoff
// degrades to the base NakDelay rather than panicking.
func deliveryCount(msg jetstream.Msg) uint64 {
	meta, err := msg.Metadata()
	if err != nil || meta == nil {
		return 1
	}
	return meta.NumDelivered
}

