package repoops

import (
	"context"
	"fmt"
	"log/slog"
	"time"

	"github.com/entireio/go-nuts/natsmsg"
	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"

	"entire.io/slogutil"
)

const tracerName = "entire.io/internal/entirecore/repoops"

// JetStreamPublisher is the slice of nats.JetStreamContext the Publisher
// needs, pulled out so tests can stub publish without a live JetStream.
type JetStreamPublisher interface {
	PublishMsg(m *nats.Msg, opts ...nats.PubOpt) (*nats.PubAck, error)
}

// Publisher publishes repo-operation jobs onto repo_ops_v1. Used by
// entire-core-global's webhook consumer to fan teardowns, App-suspends, and
// resumes out to the region that owns each placement.
//
// The publish mechanics (producer span, trace-context injection, Nats-Msg-Id,
// bounded PubAck wait) live in the shared natsmsg.LegacyPublisher; this type
// owns the domain: subject/job construction, the dedup key, and the log line.
type Publisher struct {
	pub natsmsg.LegacyPublisher
}

// NewPublisher binds a Publisher to a JetStream context.
func NewPublisher(js JetStreamPublisher) *Publisher {
	return &Publisher{pub: natsmsg.LegacyPublisher{
		JS:        js,
		Tracer:    otel.Tracer(tracerName),
		Operation: "repo.ops.publish",
	}}
}

// PublishTeardown emits one teardown job for a single placement.
// Idempotent on the op + target ULID + observedAt via the Nats-Msg-Id
// dedup header. OTel trace context rides the NATS headers so the regional
// consumer's span parents to this publish.
//
// observedAt is the removal webhook's observation time; the consumer uses
// it as the last-writer-wins threshold for its skip-if-re-added gate.
func (p *Publisher) PublishTeardown(ctx context.Context, placement Placement, target Target, githubRepoID int64, observedAt time.Time) error {
	return p.publishOp(ctx, OpTeardown, SuspendGateRemoval, placement, target, githubRepoID, 0, observedAt)
}

// PublishAppSuspend emits one App-suspend job (installation.suspend) for a
// single placement. It stamps the installation-suspended gate and carries
// installationID, so the consumer gates it on the owning installation still
// being suspended rather than on repo re-observation. observedAt only feeds
// the dedup key here; the gate is current installation state, not
// observed-after. (The removal-driven PublishSuspend is gone — every
// GitHub-side removal tears down instead, COR-454.)
func (p *Publisher) PublishAppSuspend(ctx context.Context, placement Placement, target Target, githubRepoID, installationID int64, observedAt time.Time) error {
	return p.publishOp(ctx, OpSuspend, SuspendGateInstallationSuspended, placement, target, githubRepoID, installationID, observedAt)
}

// PublishResume emits one resume job for a single placement (App
// unsuspend). observedAt is the webhook's observation time; the resume
// consumer gates on CURRENT attachment rather than observed-after, so here
// it only feeds the dedup key.
func (p *Publisher) PublishResume(ctx context.Context, placement Placement, target Target, githubRepoID int64, observedAt time.Time) error {
	return p.publishOp(ctx, OpResume, SuspendGateRemoval, placement, target, githubRepoID, 0, observedAt)
}

func (p *Publisher) publishOp(ctx context.Context, op Op, gate SuspendGate, placement Placement, target Target, githubRepoID, installationID int64, observedAt time.Time) error {
	parsed := ParsedSubject{Placement: placement, Op: op}
	subject := Subject(parsed)
	job := Job{Target: target, GitHubRepoID: githubRepoID, ObservedAt: observedAt, SuspendGate: gate, InstallationID: installationID}

	data, err := Marshal(job)
	if err != nil {
		return fmt.Errorf("marshal repo-ops job: %w", err)
	}

	// Dedup key is op + target ULID + observation time. A producer retry of
	// the same webhook collapses server-side within StreamDuplicatesWindow,
	// but a later removal of the same placement after a re-add must enqueue
	// separately; otherwise the stale first job can skip via the freshness
	// gate and lose the real teardown/suspend. The op token keeps distinct
	// ops for the same observation from collapsing into one job.
	msgID := fmt.Sprintf("%s/%s/%s", parsed.Op, target.ULID, observedAt.UTC().Format(time.RFC3339Nano))

	ack, err := p.pub.Publish(ctx, &nats.Msg{Subject: subject, Data: data}, msgID,
		attribute.String("entire.operation", string(parsed.Op)),
		attribute.String("entire.target_jurisdiction", placement.Jurisdiction),
		attribute.String("entire.target_cluster_slug", placement.ClusterSlug),
		attribute.String("entire.target_ulid", target.ULID),
	)
	if err != nil {
		return fmt.Errorf("publish repo-ops %s: %w", op, err)
	}
	slogutil.Info(ctx, "published repo-ops job",
		slog.String("op", string(op)),
		slog.String("subject", subject),
		slog.String("msg_id", msgID),
		slog.String("target_ulid", target.ULID),
		slog.Bool("duplicate", ack.Duplicate),
	)
	return nil
}

package gitjobs

import (
	"context"
	"fmt"
	"log/slog"

	"github.com/entireio/go-nuts/natsmsg"
	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"

	"entire.io/slogutil"
)

const tracerName = "entire.io/core/mirrorrepo/gitjobs"

// JetStreamPublisher is the slice of nats.JetStreamContext the
// Publisher needs. Pulled out as an interface so tests can stub
// publish without a live JetStream.
type JetStreamPublisher interface {
	PublishMsg(m *nats.Msg, opts ...nats.PubOpt) (*nats.PubAck, error)
}

// Publisher publishes git-sync jobs onto the canonical mirror_git_v1
// stream. mirror-pipeline owns the stream creation; entire-core only
// publishes. One Publisher targets one JetStream: a regional core is
// co-located with the single cluster it serves, so its git jobs always
// go to that cluster's NATS (configured via ENTIRE_MIRROR_GIT_NATS_URL).
//
// The publish mechanics (producer span, trace-context injection,
// Nats-Msg-Id, bounded PubAck wait) live in the shared
// natsmsg.LegacyPublisher; this type owns the domain: subject/job
// construction, the dedup key, and the log line.
type Publisher struct {
	pub natsmsg.LegacyPublisher
}

// NewPublisher binds a Publisher to a JetStream context.
func NewPublisher(js JetStreamPublisher) *Publisher {
	return &Publisher{pub: natsmsg.LegacyPublisher{
		JS:        js,
		Tracer:    otel.Tracer(tracerName),
		Operation: "mirror.git.publish",
	}}
}

// PublishSyncRepo emits a single sync_repo job. Idempotent on
// (placement, source, target) via the Nats-Msg-Id dedup header — a
// retry within StreamDuplicatesWindow collapses server-side, so the
// caller doesn't have to coordinate. OTel trace context rides the
// NATS headers so the worker's span parents to this publish.
//
// A nil Publisher receiver or nil js panics on call: callers MUST
// wire a publisher, and serve-mode boot enforces it (see
// buildGitJobsPublisher). Silently treating nil as "skip the publish"
// is what stranded EU mirrors in provisioning state.
func (p *Publisher) PublishSyncRepo(ctx context.Context, placement Placement, source Source, target Target) error {
	parsed := ParsedSubject{
		Placement:  placement,
		SourceKind: SourceKindGithub,
		Op:         OpSyncRepo,
	}
	job := Job{Source: source, Target: target}
	subject := Subject(parsed)

	data, err := Marshal(job)
	if err != nil {
		return fmt.Errorf("marshal git job: %w", err)
	}

	// Msg-ID dedup key: same shape mirror-pipeline's resync-scheduler
	// uses (op/source-kind/owner/repo/ulid). A retry of the *same*
	// create-mirror call collapses; a separate placement on the same
	// upstream gets a distinct key because target.ULID differs.
	msgID := fmt.Sprintf("%s/%s/%s/%s/%s",
		parsed.Op, parsed.SourceKind,
		source.Owner, source.Repo, target.ULID,
	)

	ack, err := p.pub.Publish(ctx, &nats.Msg{Subject: subject, Data: data}, msgID,
		attribute.String("entire.operation", string(parsed.Op)),
		attribute.String("entire.source_kind", string(parsed.SourceKind)),
		attribute.String("entire.target_jurisdiction", placement.Jurisdiction),
		attribute.String("entire.target_cluster_id", placement.ClusterID),
		attribute.String("entire.source_owner", source.Owner),
		attribute.String("entire.source_repo", source.Repo),
		attribute.String("entire.target_ulid", target.ULID),
	)
	if err != nil {
		return fmt.Errorf("publish git mirror job: %w", err)
	}

	slogutil.Info(ctx, "published git mirror sync_repo",
		slog.String("subject", subject),
		slog.String("msg_id", msgID),
		slog.String("source_owner", source.Owner),
		slog.String("source_repo", source.Repo),
		slog.String("target_ulid", target.ULID),
		slog.Bool("duplicate", ack.Duplicate),
	)
	return nil
}

