import (
	"context"
	"fmt"
	"log/slog"
	"time"

	"github.com/entireio/go-nuts/natsmsg"
	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	otelcodes "go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"entire.io/slogutil"
)

const tracerName = "entire.io/internal/entirecore/permssweep"

// natsMsgIDHeader is the JetStream dedup header (same constant gitjobs and
// permsbackfill use; spelt out to avoid pulling in nats.go's internal const).
const natsMsgIDHeader = "Nats-Msg-Id"

// publishTimeout bounds one synchronous PublishMsg round-trip. Load-bearing:
// the enumerator's ctx has no deadline, and PublishMsg with a deadline-free
// nats.Context waits for the PubAck indefinitely — with RetryOnFailedConnect
// the connect itself "succeeds" while NATS is down, so an unbounded publish
// would hang the CronJob forever instead of failing the tick loudly (the
// exact never-terminating-Job failure mode this fan-out exists to kill).
const publishTimeout = 15 * time.Second

// JetStreamPublisher is the slice of nats.JetStreamContext the Publisher
// needs, pulled out so tests can stub publish without a live JetStream.
type JetStreamPublisher interface {
	PublishMsg(m *nats.Msg, opts ...nats.PubOpt) (*nats.PubAck, error)
}

// Publisher emits perms_sweep jobs onto the in-cell repo_ops_v1 stream. One
// Publisher per enumerator run; the subject is fixed at construction (the
// sweep is fleet-scoped, so every job of a run rides the same subject).
type Publisher struct {
	js      JetStreamPublisher
	subject string
}

// NewPublisher binds a Publisher to a JetStream context and the enumerator's
// jurisdiction (empty publishes under the "global" token).
func NewPublisher(js JetStreamPublisher, jurisdiction string) *Publisher {
	return &Publisher{js: js, subject: subjectFor(jurisdiction)}
}

// publishMsg is the mechanical tail every perms_sweep publish shares —
// enumerator jobs, canaries, and the consumer's chunk continuations: build
// the message, stamp the JetStream dedup id, inject trace context, and run a
// publishTimeout-bounded PublishMsg (see publishTimeout for why the bound is
// load-bearing). Callers own their spans, metrics, and logging.
func publishMsg(ctx context.Context, js JetStreamPublisher, subject, msgID string, data []byte) (*nats.PubAck, error) {
	msg := &nats.Msg{Subject: subject, Data: data, Header: nats.Header{}}
	msg.Header.Set(natsMsgIDHeader, msgID)
	otel.GetTextMapPropagator().Inject(ctx, natsmsg.HeaderCarrier(msg.Header))
	pubCtx, cancel := context.WithTimeout(ctx, publishTimeout)
	defer cancel()
	return js.PublishMsg(msg, nats.Context(pubCtx)) //nolint:wrapcheck // every caller wraps with its own publish context
}

