package githubpr

import (
	"context"
	"encoding/json"
	"errors"
	"log/slog"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/entire-api/internal/otelsetup"
	"github.com/entirehq/entire-api/internal/store"
	"github.com/entireio/go-nuts/jsconsumer"
)

// consumerDurable is the durable consumer name on each cell's github_pr_v1
// stream. One per deployment, stable across restarts.
const consumerDurable = "github-pr-consumer"

// consumerMaxDeliver caps redelivery before JetStream terms a message — same
// posture as the github_meta / forwarder / ingest consumers.
const consumerMaxDeliver = 8

// PullRequestWriter is the store sink the consumer upserts PR metadata into.
type PullRequestWriter interface {
	UpsertGitHubPullRequestMeta(ctx context.Context, m store.GitHubPullRequestMeta) error
}

// Consumer durably pulls github_pr_v1 from this cell's LOCAL JetStream stream,
// filtered to this placement's (jurisdiction, cluster) subject, and upserts each
// event into the local repo store keyed by (repo ULID, PR number).
//
// Display metadata only — it NEVER gates access. The producer (mirror-pipeline
// meta-fanout) publishes one Event per resolved placement into that placement's
// local NATS, so this consumer only ever sees events for repos in this cell.
type Consumer struct {
	nc    *nats.Conn
	store PullRequestWriter
	cfg   jsconsumer.Config
	m     metrics

	run *jsconsumer.Runner
}

// NewConsumer constructs a Consumer.
func NewConsumer(nc *nats.Conn, w PullRequestWriter, jurisdiction, cluster string) *Consumer {
	return &Consumer{nc: nc, store: w, m: newMetrics(), cfg: jsconsumer.Config{
		Stream:        StreamName,
		Durable:       consumerDurable,
		FilterSubject: SubjectFor(jurisdiction, cluster),
		AckWait:       30 * time.Second,
		MaxDeliver:    consumerMaxDeliver,
		SpanName:      "github_pr.consume",
		Name:          "githubpr",
		// Tracer keeps consumer spans scoped to the service (otelsetup), not
		// the go-nuts module, so trace attribution is unchanged by the migration.
		Tracer: otelsetup.Tracer(),
	}}
}

// Start creates the durable consumer and begins consuming. Returns immediately.
// The local github_pr_v1 stream must already exist — it is provisioned
// declaratively in fleet (apps/nats-streams), not by this binary. The caller
// gates Start behind CONSUME_PULL_REQUESTS so a cell without the stream
// provisioned doesn't error here.
func (c *Consumer) Start(ctx context.Context) error {
	if c == nil || c.nc == nil {
		return errors.New("githubpr: Consumer not initialised")
	}
	if c.store == nil {
		return errors.New("githubpr: Consumer.store required")
	}
	run, err := jsconsumer.Start(ctx, c.nc, c.cfg, func(msg jetstream.Msg) { c.handle(ctx, msg) })
	if err != nil {
		return err
	}
	c.run = run
	slog.InfoContext(ctx, "github_pr consumer started", slog.String("subject", c.cfg.FilterSubject))
	return nil
}

// Stop halts the consume loop and waits for an in-flight handler to finish.
// Idempotent.
func (c *Consumer) Stop() error {
	c.run.Stop()
	return nil
}

// handle is the per-message entry point (production callback + test seam): the
// shared span+decode-or-term prologue, then onEvent for a decoded event.
func (c *Consumer) handle(ctx context.Context, msg jetstream.Msg) {
	jsconsumer.Process(ctx, msg, c.cfg, decode, c.onEvent, func(ctx context.Context) {
		c.m.dropped.Add(ctx, 1, attr("reason", "undecodable"))
	})
}

func decode(b []byte) (Event, error) {
	var ev Event
	err := json.Unmarshal(b, &ev)
	return ev, err
}

func (c *Consumer) onEvent(ctx context.Context, span trace.Span, msg jetstream.Msg, ev Event) {
	if ev.RepoULID == "" || ev.Number == 0 {
		// No key to upsert on — redelivery won't help. Term.
