package githubmeta

import (
	"context"
	"encoding/json"
	"errors"
	"log/slog"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/entire-api/internal/otelsetup"
	"github.com/entirehq/entire-api/internal/store"
	"github.com/entireio/go-nuts/jsconsumer"
)

// consumerDurable is the durable consumer name on each cell's github_meta_v1
// stream. One per deployment, stable across restarts.
const consumerDurable = "github-meta-consumer"

// consumerMaxDeliver caps redelivery before JetStream terms a message — same
// posture as the forwarder / ingest consumers.
const consumerMaxDeliver = 8

// MetaWriter is the store sink the consumer upserts display metadata into.
type MetaWriter interface {
	UpsertGitHubRepoMeta(ctx context.Context, m store.GitHubRepoMeta) error
}

// Consumer durably pulls github_meta_v1 from this cell's LOCAL JetStream
// stream, filtered to this placement's (jurisdiction, cluster) subject, and
// upserts each event into the local repo store keyed by repo ULID.
//
// Display metadata only — it NEVER gates access. The producer (mirror-pipeline
// meta-fanout) publishes one Event per resolved placement into that placement's
// local NATS, so this consumer only ever sees events for repos in this cell.
type Consumer struct {
	nc    *nats.Conn
	store MetaWriter
	cfg   jsconsumer.Config
	m     metrics

	run *jsconsumer.Runner
}

// NewConsumer constructs a Consumer.
func NewConsumer(nc *nats.Conn, w MetaWriter, jurisdiction, cluster string) *Consumer {
	return &Consumer{nc: nc, store: w, m: newMetrics(), cfg: jsconsumer.Config{
		Stream:        StreamName,
		Durable:       consumerDurable,
		FilterSubject: SubjectFor(jurisdiction, cluster),
		AckWait:       30 * time.Second,
		MaxDeliver:    consumerMaxDeliver,
		SpanName:      "github_meta.consume",
		Name:          "githubmeta",
		// Tracer keeps consumer spans scoped to the service (otelsetup), not
		// the go-nuts module, so trace attribution is unchanged by the migration.
		Tracer: otelsetup.Tracer(),
	}}
}

// Start creates the durable consumer and begins consuming. Returns immediately.
// The local github_meta_v1 stream must already exist — it is provisioned
// declaratively in fleet (apps/nats-streams, nack), not by this binary. The
// caller gates Start behind CONSUME_GITHUB_META so a cell without the stream
// provisioned doesn't error here.
func (c *Consumer) Start(ctx context.Context) error {
	if c == nil || c.nc == nil {
		return errors.New("githubmeta: Consumer not initialised")
	}
	if c.store == nil {
		return errors.New("githubmeta: Consumer.store required")
	}
	run, err := jsconsumer.Start(ctx, c.nc, c.cfg, func(msg jetstream.Msg) { c.handle(ctx, msg) })
	if err != nil {
		return err
	}
	c.run = run
	slog.InfoContext(ctx, "github_meta consumer started", slog.String("subject", c.cfg.FilterSubject))
	return nil
}

// Stop halts the consume loop and waits for an in-flight handler to finish.
// Idempotent.
func (c *Consumer) Stop() error {
	c.run.Stop()
	return nil
}

// handle is the per-message entry point (production callback + test seam): the
// shared span+decode-or-term prologue, then onEvent for a decoded event.
func (c *Consumer) handle(ctx context.Context, msg jetstream.Msg) {
	jsconsumer.Process(ctx, msg, c.cfg, decode, c.onEvent, func(ctx context.Context) {
		c.m.dropped.Add(ctx, 1, attr("reason", "undecodable"))
	})
}

func decode(b []byte) (Event, error) {
	var ev Event
	err := json.Unmarshal(b, &ev)
	return ev, err
}

func (c *Consumer) onEvent(ctx context.Context, span trace.Span, msg jetstream.Msg, ev Event) {
	if ev.RepoULID == "" {
		// No key to upsert on — redelivery won't help. Term.
		slog.WarnContext(ctx, "githubmeta: github_meta_v1 missing repo_ulid; term", slog.String("subject", msg.Subject()))
		c.m.dropped.Add(ctx, 1, attr("reason", "missing_repo_ulid"))
		_ = msg.Term()
		return
	}
	ctx = otelsetup.WithBaggage(ctx, otelsetup.RepoIDAttr(ev.RepoULID))
	if err := c.store.UpsertGitHubRepoMeta(ctx, toRow(ev)); err != nil {
		// Transient (DB blip) — nak for redelivery.
		span.RecordError(err)
		span.SetStatus(codes.Error, "upsert")
		slog.WarnContext(ctx, "githubmeta: upsert github_repo_meta failed; nak", slog.Any("error", err), slog.String("repo_ulid", ev.RepoULID))
		_ = msg.Nak()
		return
	}
	c.m.written.Add(ctx, 1)
	_ = msg.Ack()
	// Metadata webhooks are low frequency, so a per-event success line is fine.
	slog.InfoContext(ctx, "githubmeta: github_repo_meta upserted", slog.String("repo_ulid", ev.RepoULID))
}

// toRow maps a decoded wire Event to the store row. Display fields are copied
// verbatim; observed_at carries the producer's webhook-receipt time, which is
// the store's reorder guard.
//
// private/archived are version-gated: only a schema_version >= 2 producer emits
// them, so for older (v1) events we pass nil — leaving the columns NULL ("not yet
// observed at v2") rather than persisting a fabricated false. At v2 the producer
// always sends them, so a false is a real observation worth recording.
func toRow(ev Event) store.GitHubRepoMeta {
	m := store.GitHubRepoMeta{
		RepoID:          ev.RepoULID,
		GitHubRepoID:    ev.GitHubRepoID,
		FullName:        ev.FullName,
		Description:     ev.Description,
		HTMLURL:         ev.HTMLURL,
		Language:        ev.Language,
		StargazersCount: ev.StargazersCount,
		ForksCount:      ev.ForksCount,
		Topics:          ev.Topics,
		PushedAt:        ev.PushedAt,
		ObservedAt:      ev.ObservedAt,
	}
	if ev.SchemaVersion >= SchemaVersionPrivateArchived {
		m.Private = &ev.Private
		m.Archived = &ev.Archived
	}
	return m
}

package userlifecycle

import (
	"context"
	"encoding/json"
	"errors"
	"log/slog"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/entire-api/internal/otelsetup"
	"github.com/entireio/go-nuts/jsconsumer"
)

// consumerDurable is the durable consumer name on each cell's
// resource_lifecycle_v1 stream. One per deployment, stable across restarts;
// distinct from the repo-seeding consumer (repo-lifecycle-consumer) and the
// re-attribution consumer (author-reattribute-consumer) that bind other arms of
// the same stream.
const consumerDurable = "user-lifecycle-consumer"

// consumerMaxDeliver caps redelivery before JetStream terms a message — same
// posture as the repo lifecycle / reattribute consumers.
const consumerMaxDeliver = 8

// consumerCfg is the durable pull-consumer descriptor: the user arm of the
// stream, expressed as FilterSubjects (plural) to preserve the existing
// on-server filter form exactly.
var consumerCfg = jsconsumer.Config{
	Stream:         StreamName,
	Durable:        consumerDurable,
	FilterSubjects: []string{subjectUser},
	AckWait:        30 * time.Second,
	MaxDeliver:     consumerMaxDeliver,
	SpanName:       "userlifecycle.consume",
	Name:           "userlifecycle",
	// Tracer keeps consumer spans scoped to the service (otelsetup), not the
	// go-nuts module, so trace attribution is unchanged by the migration.
	Tracer: otelsetup.Tracer(),
}

// Store is the user-store surface this consumer needs: the account-scoped purge.
type Store interface {
	DeleteUserData(ctx context.Context, accountID string) error
}

// Consumer durably pulls the user arm of this cell's local resource_lifecycle_v1
// stream and purges a deleted account's rows from the user store.
type Consumer struct {
	nc    *nats.Conn
	store Store
	m     metrics

	run *jsconsumer.Runner
}

// NewConsumer constructs a Consumer over the user store.
func NewConsumer(nc *nats.Conn, st Store) *Consumer {
	return &Consumer{nc: nc, store: st, m: newMetrics()}
}

// Start creates the durable consumer and begins consuming. Returns immediately.
// The local resource_lifecycle_v1 stream must already exist (provisioned in
// fleet); the caller gates Start behind CONSUME_USER_LIFECYCLE so a cell without
// the stream doesn't error in CreateOrUpdateConsumer.
func (c *Consumer) Start(ctx context.Context) error {
	if c == nil || c.nc == nil {
		return errors.New("userlifecycle: Consumer not initialised")
	}
	if c.store == nil {
		return errors.New("userlifecycle: Consumer.store required")
	}
	run, err := jsconsumer.Start(ctx, c.nc, consumerCfg, func(msg jetstream.Msg) { c.handle(ctx, msg) })
	if err != nil {
		return err
	}
	c.run = run
	slog.InfoContext(ctx, "resource_lifecycle user purge consumer started")
	return nil
}

// Stop halts the consume loop and waits for an in-flight handler to finish.
// Idempotent.
func (c *Consumer) Stop() error {
	c.run.Stop()
	return nil
}

// handle is the per-message entry point (production callback + test seam): the
// shared span+decode-or-term prologue, then onEvent for a decoded event.
func (c *Consumer) handle(ctx context.Context, msg jetstream.Msg) {
	jsconsumer.Process(ctx, msg, consumerCfg, decode, c.onEvent, func(ctx context.Context) {
		c.m.dropped.Add(ctx, 1, attr("reason", "undecodable"))
	})
}

func decode(b []byte) (Event, error) {
	var ev Event
	err := json.Unmarshal(b, &ev)
	return ev, err
}

func (c *Consumer) onEvent(ctx context.Context, span trace.Span, msg jetstream.Msg, ev Event) {
	if ev.ResourceType != typeUser {
		// The filter subject is the user arm, so this is defensive only — ack rather
		// than churn redelivery on a misrouted event.
		c.m.skipped.Add(ctx, 1, attr("reason", "not_user"))
		_ = msg.Ack()
		return
	}
	if ev.ResourceID == "" {
		// No account to act on — redelivery won't help. Term.
		slog.WarnContext(ctx, "userlifecycle: event missing account id; term", slog.String("subject", msg.Subject()))
		c.m.dropped.Add(ctx, 1, attr("reason", "missing_account"))
		_ = msg.Term()
		return
	}

	switch ev.Op {
	case opDeleted:
		if err := c.store.DeleteUserData(ctx, ev.ResourceID); err != nil {
			span.RecordError(err)
			span.SetStatus(codes.Error, "purge")
