// Package natspub is the shared JetStream publish seam behind the typed job
// publishers (metajobs, prjobs, pushauthorjobs, donejobs, mirrorjobs): each
// jobs package keeps its typed Publisher and owns the domain parts — subject,
// msg-id, payload, span/log attributes, the one INFO log per publish — and
// delegates the publish mechanics (producer span, trace-context injection,
// Nats-Msg-Id dedup header, bounded pub-ack wait, PubAck telemetry) to
// go-nuts natsmsg.LegacyPublisher, so every job stream gets identical
// tracing, deduplication, and backpressure behavior.
package natspub

import (
	"context"
	"fmt"
	"log/slog"
	"time"

	"github.com/entireio/go-nuts/natsmsg"
	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
)

// MsgIDHeader is the JetStream deduplication header.
const MsgIDHeader = "Nats-Msg-Id"

// AckWait bounds the synchronous pub-ack wait (matches the nats.go default
// request wait). The callers' contexts are process-lifetime or per-message
// handler contexts, so a publish routed to a reconnecting NATS (or remote
// region) would sit in the client's reconnect buffer until the connection
// returned, stalling the serial consume loop. A bounded wait turns that into
// an error the caller can act on (consumer Nak → JetStream redelivery).
const AckWait = 5 * time.Second

// JetStreamPublisher is the subset of nats.JetStreamContext needed for
// publish — go-nuts natsmsg.LegacyJetStream, re-exported under the name the
// typed publishers alias.
type JetStreamPublisher = natsmsg.LegacyJetStream

// Publication describes one job publish: where it goes, how it dedups, and how
// it is named in spans, logs, and errors.
type Publication struct {
	// Tracer names the otel tracer the producer span starts from.
	Tracer string
	// SpanName is the producer span name, e.g. "github_meta.publish".
	SpanName string
	// ErrKind labels failures: "marshal <ErrKind>: …" / "publish <ErrKind>: …".
	ErrKind string
	// LogMsg is the INFO message logged after a successful publish.
	LogMsg string

	// Subject is the fully-resolved NATS subject.
	Subject string
	// MsgID is the JetStream dedup id, set as the Nats-Msg-Id header.
	MsgID string
	// Marshal renders the job payload.
	Marshal func() ([]byte, error)

	// SpanAttrs are the domain span attributes, appended to the standard
	// messaging.* set.
	SpanAttrs []attribute.KeyValue
	// LogAttrs are the domain log attributes, logged ahead of the standard
	// subject/msg_id/sequence/duplicate set.
	LogAttrs []slog.Attr
}

// PlacementAttrs is the standard span-attribute pair for a placement-scoped
// subject (jurisdiction, cluster).
func PlacementAttrs(jurisdiction, cluster string) []attribute.KeyValue {
	return []attribute.KeyValue{
		attribute.String("entire.target_jurisdiction", jurisdiction),
		attribute.String("entire.target_cluster_id", cluster),
	}
}

// Publish runs one publication against js: marshal the payload, then hand the
// message to natsmsg.LegacyPublisher (producer span named pub.SpanName,
// trace-context injection, Nats-Msg-Id, AckWait-bounded pub-ack, PubAck
// telemetry), and log the one INFO line. A marshal failure returns before any
// span exists — payload encoding is the caller's domain, not the publish hop.
func Publish(ctx context.Context, js JetStreamPublisher, pub Publication) error {
	data, err := pub.Marshal()
	if err != nil {
		return fmt.Errorf("marshal %s: %w", pub.ErrKind, err)
	}

	lp := natsmsg.LegacyPublisher{
		JS:        js,
		Tracer:    otel.Tracer(pub.Tracer),
		Timeout:   AckWait,
		Operation: pub.SpanName,
	}
	ack, err := lp.Publish(ctx, &nats.Msg{Subject: pub.Subject, Data: data}, pub.MsgID, pub.SpanAttrs...)
	if err != nil {
		return fmt.Errorf("publish %s: %w", pub.ErrKind, err)
	}

	logAttrs := append(append([]slog.Attr{}, pub.LogAttrs...),
		slog.String("subject", pub.Subject),
		slog.String("msg_id", pub.MsgID),
		slog.Uint64("sequence", ack.Sequence),
		slog.Bool("duplicate", ack.Duplicate),
	)
	slog.LogAttrs(ctx, slog.LevelInfo, pub.LogMsg, logAttrs...)
	return nil
}

