307	func assertProducerSpan(t *testing.T, rec *tracetest.SpanRecorder, wantName string, wantTrace trace.TraceID) {
308		t.Helper()
309		spans := rec.Ended()
310		if len(spans) != 1 {
311			t.Fatalf("ended spans = %d, want 1", len(spans))
312		}
313		span := spans[0]
314		if span.Name() != wantName {
315			t.Errorf("span name = %q, want %q", span.Name(), wantName)
316		}
317		if span.SpanKind() != trace.SpanKindProducer {
318			t.Errorf("span kind = %v, want producer", span.SpanKind())
319		}
320		if span.SpanContext().TraceID() != wantTrace {
321			t.Errorf("span trace id = %s, want the producer's %s (span did not re-parent)", span.SpanContext().TraceID(), wantTrace)
322		}
323		seen := map[attribute.Key]bool{}
324		got := map[attribute.Key]attribute.Value{}
325		for _, kv := range span.Attributes() {
326			got[kv.Key] = kv.Value
327			seen[kv.Key] = true
328		}
329		for key, want := range map[attribute.Key]string{
330			"messaging.system":           "nats",
331			"messaging.operation.type":   "publish",
332			"messaging.destination.name": "pub.repo",
333			"messaging.message.id":       "msg-1",
334			"messaging.nats.stream":      testStream,
335			"entire.target_ulid":         "ulid-1", // caller-forwarded domain attr
336		} {
337			if got[key].AsString() != want {
338				t.Errorf("span attr %s = %q, want %q", key, got[key].AsString(), want)
339			}
340		}
341		if got["entire.github_repo_id"].AsInt64() != 42 {
342			t.Errorf("caller-forwarded entire.github_repo_id = %d, want 42", got["entire.github_repo_id"].AsInt64())
343		}
344		// messaging.operation.name is reserved for the system-specific operation
345		// (send/ack/nack), not the application span name — it must not carry wantName.
346		if seen["messaging.operation.name"] {
347			t.Errorf("messaging.operation.name = %q set; the caller span name belongs on the span name only", got["messaging.operation.name"].AsString())
348		}
349		if got["messaging.nats.sequence"].AsInt64() != 7 {
350			t.Errorf("sequence attr = %d, want 7", got["messaging.nats.sequence"].AsInt64())
351		}
352		if !got["messaging.nats.duplicate"].AsBool() {
353			t.Error("duplicate attr = false, want true")
354		}
